import type { VariableConfig } from '../../Variable';
/**
 * Configuration type for multi-line text variables
 */
export type MultiLineTextVariableType<Type extends string = string> = VariableConfig<Type>;
/**
 * A Variable for a multi-line text field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the multi-line text variable including:
 *   * **question** - Question text displayed to the user
 *   * And all other properties from the base Variable type
 */
export declare function MultiLineTextVariable(config: MultiLineTextVariableType): MultiLineTextVariableType<string>;
